import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"57、【巽】 巽下巽上","description":"周易口诀义 - 57、【巽】 巽下巽上","frontmatter":{"title":"57、【巽】 巽下巽上","description":"周易口诀义 - 57、【巽】 巽下巽上"},"headers":[],"relativePath":"zh/classics/koujueyi/059.md","filePath":"zh/classics/koujueyi/059.md"}'),r={name:"zh/classics/koujueyi/059.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_57、【巽】-巽下巽上" tabindex="-1">57、【巽】 巽下巽上 <a class="header-anchor" href="#_57、【巽】-巽下巽上" aria-label="Permalink to “57、【巽】 巽下巽上”">​</a></h1><p>彖曰：重巽以申命。刚巽乎中正而志行，柔皆顺乎刚，是以「小亨，利有攸往，利见大人」。</p><p>象曰：随风，巽，君子以申命行事。</p><p>初六：进退，利武人之贞。</p><p>象曰：「进退」，志疑也。「利武人之贞」，志治也。</p><p>九二：巽在床下，用史巫纷若，吉，无咎。</p><p>象曰：「纷若」之「吉」，得中也。</p><p>九三：频巽，吝。</p><p>象曰：「频巽」之「吝」，志穷也。</p><p>六四：悔亡，田获三品。</p><p>象曰：「田获三品」，有功也。</p><p>九五：贞吉，悔亡，无不利，无初有终，先庚三日，后庚三日，吉。</p><p>象曰：九五之「吉」，位正中也。</p><p>上九：巽在床下，丧其资斧，贞凶。</p><p>象曰：「巽在床下」，上穷也。「丧其资斧」，正乎凶也。</p><p>解读</p><p>「巽小亨」者，「巽」是卑顺之名，和入为义，故谓之「巽」也。夫人用巽，必须恭俭庄敬，进退合宜，若过于卑巽，逾尊卑之分，敬恭不合礼，即所通非大，故曰「小亨」也。「利有攸往」者，巽顺以行，物不违拒，故曰「利有攸往」也。「利见大人」者，人用巽顺，即无往不利，大人用巽，其道愈隆，巽顺之美，上下皆须之，故曰「利见大人」也。象曰「随风，巽」者，按说卦云：「巽，入也。」风之所入，物无不顺，风相随而行，故曰「随风，巽」也。君子以申命行事者，风行草偃，亦有王者风教行于天下意，故君子象此，申其命令，行其政教之事也。</p><p>「初六，进退，利武人之贞」者，出令之初，人未从化，心怀犹豫，进退迟疑；申命之初，人未信服，成命齐邦，莫过威武以整齐之，故曰「进退，利武人之贞」也。</p><p>「九二，巽在床下，用史巫纷若，吉，无咎」者，史谓祝史，巫谓巫觋，皆是接事鬼神之人。九二处巽之中，在下位，而以阳居阴，卑巽而顺，故曰「巽在床下」者，卑谦过甚，失于正道，咎过生焉。然鬼神无形，所在怠慢，九二卑恭如是，事神祗而获多福，故曰「用史巫纷若，吉，无咎」也。纷者，盛多之貌也。</p><p>「九三，频巽，吝」者，频是频蹙不乐之貌也。九三体刚居正，为四所乘，志意穷屈，不得舒畅，故怀频蹙，即是鄙吝之道，故曰「频巽，吝」。</p><p>「六四，悔亡，田获三品」者，六四乘九三之刚，所以有悔；然得位乘五，上奉君命，所以「悔亡」。亲近至尊，即是权臣，以斯行命，必有功劳，譬之田猎而获三品之物，故曰「田获三品」也。一曰乾豆为豆实，以奉宗庙；二曰宾客以助君明目达聪；三曰充君之庖厨，供君之费也。</p><p>九五，贞吉，悔亡，无不利，无初有终。「先庚三日，后庚三日，吉」者，五以刚居位，违于谦巽，故有忧悔；能用中正以宣命令，人不敢违，所以「悔亡」而「无不利」也。初施命令，新用刚直，人未从化，故曰「无初」；以中正之德，宣布命令，人渐从化，故曰「有终」也。申命令谓之庚。以人迷既久，不可卒然而理，故先申三日，慇懃劝谕，使其变恶从善。令著之后，复再申三日，人若不从，即当诛罚，民服其罪，所以获吉，故曰「先庚三日，后庚三日，吉」也。</p><p>上九，巽在床下，丧其资斧，贞凶者，处巽之极，言巽过甚，似巽于床下。斧者，是斩断之物，喻决断威制。今既处上，固合威断，临下而乃过于谦，即是丧其威断，是正道之失，故曰「丧其资斧，贞凶」也。</p>',23)])])}const u=e(r,[["render",i]]);export{h as __pageData,u as default};
